CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_next_sku(p_seller_id uuid, p_prefix text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_max_num INTEGER;
  v_next_num INTEGER;
  v_candidate TEXT;
BEGIN
  -- Find the highest existing SKU number for this prefix+seller
  SELECT COALESCE(MAX(
    CASE 
      WHEN sku ~ ('^' || p_prefix || '-\d+$')
      THEN (regexp_replace(sku, '^' || p_prefix || '-0*', ''))::INTEGER
      ELSE 0
    END
  ), 0)
  INTO v_max_num
  FROM products
  WHERE seller_id = p_seller_id
    AND sku LIKE p_prefix || '-%'
    AND deleted_at IS NULL;

  v_next_num := v_max_num + 1;
  v_candidate := p_prefix || '-' || LPAD(v_next_num::TEXT, 3, '0');

  RETURN v_candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.block_user(p_blocked_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_block_id UUID;
BEGIN
    -- Нельзя заблокировать себя
    IF v_user_id = p_blocked_id THEN
        RAISE EXCEPTION 'Cannot block yourself';
    END IF;

    -- Проверяем что пользователь существует
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_blocked_id) THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- Вставляем блокировку (если уже есть — игнорируем)
    INSERT INTO blocked_users (blocker_id, blocked_id)
    VALUES (v_user_id, p_blocked_id)
    ON CONFLICT (blocker_id, blocked_id) DO NOTHING
    RETURNING id INTO v_block_id;

    -- Удаляем follow в обе стороны
    DELETE FROM follows
    WHERE (follower_id = v_user_id AND following_id = p_blocked_id)
       OR (follower_id = p_blocked_id AND following_id = v_user_id);

    -- Мягко удаляем conversations между пользователями
    UPDATE conversations
    SET deleted_at = NOW()
    WHERE deleted_at IS NULL
      AND ((buyer_id = v_user_id AND seller_id = p_blocked_id)
        OR (buyer_id = p_blocked_id AND seller_id = v_user_id));

    RETURN jsonb_build_object(
        'success', true,
        'block_id', COALESCE(v_block_id, (
            SELECT id FROM blocked_users
            WHERE blocker_id = v_user_id AND blocked_id = p_blocked_id
        ))
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.unblock_user(p_blocked_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_deleted INT;
BEGIN
    DELETE FROM blocked_users
    WHERE blocker_id = v_user_id AND blocked_id = p_blocked_id;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', v_deleted > 0,
        'was_blocked', v_deleted > 0
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_phone_exists(phone_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  normalized_phone text;
begin
  normalized_phone := regexp_replace(phone_input, '[^0-9+]', '', 'g');

  return exists (
    select 1 
    from public.user_profiles up
    where regexp_replace(up.phone, '[^0-9+]', '', 'g') = normalized_phone
      and up.deleted_at is null
      and up.phone_verified = true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_seller_shipping_settings(p_flat_rate numeric, p_additional_item_fee numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF p_flat_rate IS NULL OR p_flat_rate < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Flat shipping rate must be >= 0');
    END IF;

    IF p_additional_item_fee IS NULL OR p_additional_item_fee < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Additional item fee must be >= 0');
    END IF;

    INSERT INTO user_settings (user_id, default_flat_shipping_rate, default_additional_item_fee)
    VALUES (v_user_id, p_flat_rate, p_additional_item_fee)
    ON CONFLICT (user_id) DO UPDATE SET
        default_flat_shipping_rate = EXCLUDED.default_flat_shipping_rate,
        default_additional_item_fee = EXCLUDED.default_additional_item_fee,
        updated_at = NOW();

    RETURN jsonb_build_object(
        'success', true,
        'default_flat_shipping_rate', p_flat_rate,
        'default_additional_item_fee', p_additional_item_fee
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_seller_shipping_settings()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_flat NUMERIC(10,2);
    v_additional NUMERIC(10,2);
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    SELECT default_flat_shipping_rate, default_additional_item_fee
    INTO v_flat, v_additional
    FROM user_settings
    WHERE user_id = v_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'default_flat_shipping_rate', v_flat,
        'default_additional_item_fee', v_additional,
        'is_configured', (v_flat IS NOT NULL)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_total_unread_count()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_total INT := 0;
BEGIN
  IF v_user_id IS NULL THEN RETURN 0; END IF;

  SELECT COALESCE(SUM(
    CASE 
      WHEN c.buyer_id = v_user_id THEN c.buyer_unread_count
      WHEN c.seller_id = v_user_id THEN c.seller_unread_count
      ELSE 0
    END
  ), 0) INTO v_total
  FROM conversations c
  WHERE c.deleted_at IS NULL AND (c.buyer_id = v_user_id OR c.seller_id = v_user_id);

  RETURN v_total;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_user_blocked(p_other_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_i_blocked BOOLEAN;
    v_they_blocked BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM blocked_users
        WHERE blocker_id = v_user_id AND blocked_id = p_other_user_id
    ) INTO v_i_blocked;

    SELECT EXISTS (
        SELECT 1 FROM blocked_users
        WHERE blocker_id = p_other_user_id AND blocked_id = v_user_id
    ) INTO v_they_blocked;

    RETURN jsonb_build_object(
        'is_blocked', v_i_blocked OR v_they_blocked,
        'i_blocked_them', v_i_blocked,
        'they_blocked_me', v_they_blocked
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_product_shipping(p_product_id uuid, p_quantity integer DEFAULT 1)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product RECORD;
    v_flat_rate NUMERIC(10,2);
    v_additional_fee NUMERIC(10,2);
BEGIN
    SELECT 
        p.seller_id,
        p.free_shipping,
        p.use_seller_default_shipping,
        p.custom_flat_shipping_cost,
        p.custom_additional_item_fee,
        p.shipping_price
    INTO v_product
    FROM products p
    WHERE p.id = p_product_id AND p.deleted_at IS NULL;

    IF NOT FOUND THEN RETURN 0; END IF;

    -- 1) Free shipping → $0
    IF v_product.free_shipping = TRUE THEN
        RETURN 0;
    END IF;

    -- 2) Product custom override
    IF v_product.use_seller_default_shipping = FALSE THEN
        v_flat_rate := COALESCE(v_product.custom_flat_shipping_cost, 0);
        v_additional_fee := COALESCE(v_product.custom_additional_item_fee, 0);
    ELSE
        -- 3) Seller default settings
        SELECT us.default_flat_shipping_rate, us.default_additional_item_fee
        INTO v_flat_rate, v_additional_fee
        FROM user_settings us
        WHERE us.user_id = v_product.seller_id;

        IF v_flat_rate IS NULL THEN
            -- 4) Legacy fallback: old shipping_price field
            v_flat_rate := COALESCE(v_product.shipping_price, 0);
            v_additional_fee := 0;
        ELSE
            v_additional_fee := COALESCE(v_additional_fee, 0);
        END IF;
    END IF;

    -- Formula: flat + additional × (qty - 1)
    IF p_quantity <= 1 THEN
        RETURN v_flat_rate;
    ELSE
        RETURN v_flat_rate + (v_additional_fee * (p_quantity - 1));
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_product_shipping_info(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product RECORD;
    v_flat_rate NUMERIC(10,2);
    v_additional_fee NUMERIC(10,2);
    v_source TEXT;
BEGIN
    SELECT 
        p.seller_id, p.free_shipping, p.use_seller_default_shipping,
        p.custom_flat_shipping_cost, p.custom_additional_item_fee, p.shipping_price
    INTO v_product
    FROM products p
    WHERE p.id = p_product_id AND p.deleted_at IS NULL;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Product not found');
    END IF;

    IF v_product.free_shipping = TRUE THEN
        RETURN jsonb_build_object(
            'success', true, 'free_shipping', true,
            'flat_rate', 0, 'additional_item_fee', 0, 'source', 'free'
        );
    END IF;

    IF v_product.use_seller_default_shipping = FALSE THEN
        v_flat_rate := COALESCE(v_product.custom_flat_shipping_cost, 0);
        v_additional_fee := COALESCE(v_product.custom_additional_item_fee, 0);
        v_source := 'product_custom';
    ELSE
        SELECT us.default_flat_shipping_rate, us.default_additional_item_fee
        INTO v_flat_rate, v_additional_fee
        FROM user_settings us
        WHERE us.user_id = v_product.seller_id;

        IF v_flat_rate IS NOT NULL THEN
            v_additional_fee := COALESCE(v_additional_fee, 0);
            v_source := 'seller_default';
        ELSE
            v_flat_rate := COALESCE(v_product.shipping_price, 0);
            v_additional_fee := 0;
            v_source := 'legacy';
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'free_shipping', false,
        'flat_rate', v_flat_rate,
        'additional_item_fee', v_additional_fee,
        'source', v_source
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_review(p_order_id uuid, p_rating integer, p_content text DEFAULT NULL::text, p_title character varying DEFAULT NULL::character varying, p_would_recommend boolean DEFAULT NULL::boolean, p_image_urls text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_order RECORD;
    v_product_id UUID;
    v_seller_id UUID;
    v_review_id UUID;
    v_existing_review UUID;
    v_image_url TEXT;
    v_sort_order INTEGER := 0;
BEGIN
    -- 1. Auth check
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- 2. Validate rating
    IF p_rating < 1 OR p_rating > 5 THEN
        RAISE EXCEPTION 'Rating must be between 1 and 5';
    END IF;

    -- 3. Validate content length (if provided)
    IF p_content IS NOT NULL AND LENGTH(TRIM(p_content)) < 20 THEN
        RAISE EXCEPTION 'Review content must be at least 20 characters';
    END IF;

    IF p_content IS NOT NULL AND LENGTH(p_content) > 500 THEN
        RAISE EXCEPTION 'Review content must not exceed 500 characters';
    END IF;

    -- 4. Get order info and validate
    SELECT o.id, o.buyer_id, o.seller_id, o.status, o.delivered_at
    INTO v_order
    FROM orders o
    WHERE o.id = p_order_id AND o.deleted_at IS NULL;

    IF v_order IS NULL THEN
        RAISE EXCEPTION 'Order not found';
    END IF;

    IF v_order.buyer_id != v_user_id THEN
        RAISE EXCEPTION 'You can only review orders you purchased';
    END IF;

    IF v_order.status != 'delivered' THEN
        RAISE EXCEPTION 'Can only review delivered orders';
    END IF;

    v_seller_id := v_order.seller_id;

    -- 5. Get product from order items
    SELECT oi.product_id INTO v_product_id
    FROM order_items oi
    WHERE oi.order_id = p_order_id
    LIMIT 1;

    -- 6. Check for existing review
    SELECT r.id INTO v_existing_review
    FROM reviews r
    WHERE r.order_id = p_order_id 
      AND r.reviewer_id = v_user_id 
      AND r.role = 'as_seller'
      AND r.deleted_at IS NULL;

    IF v_existing_review IS NOT NULL THEN
        RAISE EXCEPTION 'You have already reviewed this order';
    END IF;

    -- 7. Create the review
    INSERT INTO reviews (
        reviewer_id,
        reviewed_id,
        order_id,
        product_id,
        role,
        rating,
        title,
        content,
        would_recommend
    )
    VALUES (
        v_user_id,
        v_seller_id,
        p_order_id,
        v_product_id,
        'as_seller',
        p_rating,
        p_title,
        TRIM(p_content),
        p_would_recommend
    )
    RETURNING id INTO v_review_id;

    -- 8. Add review images (if provided)
    IF p_image_urls IS NOT NULL AND array_length(p_image_urls, 1) > 0 THEN
        FOREACH v_image_url IN ARRAY p_image_urls
        LOOP
            INSERT INTO review_images (review_id, image_url, sort_order)
            VALUES (v_review_id, v_image_url, v_sort_order);
            v_sort_order := v_sort_order + 1;
        END LOOP;
    END IF;

    -- 9. Create notification for seller
    INSERT INTO notifications (
        user_id,
        type,
        title,
        body,
        related_user_id,
        related_product_id,
        related_order_id,
        action_url
    )
    VALUES (
        v_seller_id,
        'new_review',
        'New Review Received',
        v_user_id || ' left a ' || p_rating || '-star review',
        v_user_id,
        v_product_id,
        p_order_id,
        '/reviews/' || v_review_id
    );

    -- 10. Return success
    RETURN jsonb_build_object(
        'success', true,
        'review_id', v_review_id,
        'rating', p_rating,
        'message', 'Review submitted successfully'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_conversation(p_conversation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Soft delete только если пользователь участник чата
  UPDATE conversations
  SET deleted_at = NOW()
  WHERE id = p_conversation_id
    AND deleted_at IS NULL
    AND (buyer_id = v_user_id OR seller_id = v_user_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found or access denied';
  END IF;

  -- Soft delete всех сообщений в этом чате
  UPDATE messages
  SET deleted_at = NOW()
  WHERE conversation_id = p_conversation_id
    AND deleted_at IS NULL;

  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_app_initial_data(p_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_profile JSON;
  v_stripe JSON;
  v_user_settings JSON;
  v_categories JSON;
  v_subcategories JSON;
  v_conditions JSON;
  v_shipping_addresses JSON;
BEGIN
  SELECT row_to_json(u) INTO v_user_profile
  FROM user_profiles u
  WHERE u.user_id = p_user_id
  LIMIT 1;

  SELECT row_to_json(s) INTO v_stripe
  FROM stripe_accounts s
  WHERE s.user_id = p_user_id
  LIMIT 1;

  SELECT row_to_json(us) INTO v_user_settings
  FROM user_settings us
  WHERE us.user_id = p_user_id
  LIMIT 1;

  SELECT json_agg(c ORDER BY c.name) INTO v_categories
  FROM categories c
  WHERE c.is_active = true;

  SELECT json_agg(sc) INTO v_subcategories
  FROM subcategories sc;

  SELECT json_agg(co) INTO v_conditions
  FROM conditions co;

  SELECT json_agg(sa ORDER BY sa.is_default DESC, sa.created_at DESC) 
  INTO v_shipping_addresses
  FROM shipping_addresses sa
  WHERE sa.user_id = p_user_id
    AND sa.deleted_at IS NULL;

  RETURN json_build_object(
    'user_profile', v_user_profile,
    'stripe', v_stripe,
    'user_settings', v_user_settings,
    'categories', COALESCE(v_categories, '[]'::json),
    'subcategories', COALESCE(v_subcategories, '[]'::json),
    'conditions', COALESCE(v_conditions, '[]'::json),
    'shipping_addresses', COALESCE(v_shipping_addresses, '[]'::json)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.derive_stripe_account_status(p_charges_enabled boolean, p_payouts_enabled boolean, p_details_submitted boolean, p_requirements jsonb DEFAULT '{}'::jsonb)
 RETURNS stripe_account_status
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_disabled_reason text;
  v_past_due text[];
BEGIN
  -- Check if account was rejected
  v_disabled_reason := p_requirements->>'disabled_reason';
  IF v_disabled_reason IS NOT NULL THEN
    IF v_disabled_reason = 'rejected.other' OR 
       v_disabled_reason LIKE 'rejected.%' THEN
      RETURN 'rejected';
    END IF;
  END IF;

  -- Fully enabled
  IF p_charges_enabled AND p_payouts_enabled AND p_details_submitted THEN
    RETURN 'enabled';
  END IF;

  -- Details submitted but not yet enabled — could be in_review or restricted
  IF p_details_submitted THEN
    -- Check if there are past_due requirements (restricted)
    v_past_due := ARRAY(
      SELECT jsonb_array_elements_text(
        COALESCE(p_requirements->'past_due', '[]'::jsonb)
      )
    );

    IF array_length(v_past_due, 1) > 0 THEN
      RETURN 'restricted';
    END IF;

    -- Has charges or payouts but not both
    IF p_charges_enabled OR p_payouts_enabled THEN
      RETURN 'restricted';
    END IF;

    -- Just submitted, waiting for review
    RETURN 'in_review';
  END IF;

  -- Haven't submitted details yet
  RETURN 'onboarding';
END;
$function$

CREATE OR REPLACE FUNCTION public.create_shortlist(p_name character varying, p_event_name character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_is_public boolean DEFAULT true, p_save_as_draft boolean DEFAULT false, p_description text DEFAULT NULL::text, p_discount_percentage numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_shortlist_id UUID;
    v_share_code VARCHAR(20);
    v_status shortlist_status;
BEGIN
    -- Auth check
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    -- Validation
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shortlist name is required');
    END IF;

    IF LENGTH(TRIM(p_name)) > 100 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Name must be 100 characters or less');
    END IF;

    IF p_start_date IS NOT NULL AND p_end_date IS NOT NULL AND p_end_date < p_start_date THEN
        RETURN jsonb_build_object('success', false, 'error', 'End date cannot be before start date');
    END IF;

    IF p_discount_percentage IS NOT NULL AND (p_discount_percentage < 0 OR p_discount_percentage > 100) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Discount must be between 0 and 100');
    END IF;

    -- Status
    v_status := CASE 
        WHEN p_save_as_draft THEN 'draft'::shortlist_status 
        ELSE 'active'::shortlist_status 
    END;

    -- Insert
    INSERT INTO shortlists (
        name,
        event_name,
        description,
        start_date,
        end_date,
        is_public,
        status,
        discount_percentage,
        seller_id
    )
    VALUES (
        TRIM(p_name),
        NULLIF(TRIM(COALESCE(p_event_name, '')), ''),
        NULLIF(TRIM(COALESCE(p_description, '')), ''),
        p_start_date,
        p_end_date,
        p_is_public,
        v_status,
        COALESCE(p_discount_percentage, 0),
        v_user_id
    )
    RETURNING id, share_code INTO v_shortlist_id, v_share_code;

    RETURN jsonb_build_object(
        'success', true,
        'shortlist_id', v_shortlist_id,
        'share_code', v_share_code,
        'status', v_status
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_next_sku_number(p_sku_prefix character varying, p_exclude_product_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_max_number INTEGER := 0;
  v_next_number INTEGER;
  v_next_formatted VARCHAR;
  v_prefix_clean VARCHAR;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_sku_prefix IS NULL OR TRIM(p_sku_prefix) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'SKU prefix is required');
  END IF;

  v_prefix_clean := UPPER(TRIM(p_sku_prefix));

  SELECT COALESCE(
    MAX(
      CASE 
        WHEN sku_number ~ '^\d+$' THEN sku_number::INTEGER
        ELSE 0
      END
    ), 
    0
  )
  INTO v_max_number
  FROM products
  WHERE seller_id = v_user_id
    AND deleted_at IS NULL
    AND UPPER(sku) = v_prefix_clean
    AND (p_exclude_product_id IS NULL OR id != p_exclude_product_id);

  v_next_number := v_max_number + 1;
  v_next_formatted := LPAD(v_next_number::TEXT, 3, '0');

  -- Пропускаем занятые номера (защита от дырок в нумерации)
  WHILE EXISTS (
    SELECT 1 FROM products
    WHERE seller_id = v_user_id
      AND deleted_at IS NULL
      AND UPPER(sku) = v_prefix_clean
      AND sku_number = v_next_formatted
      AND (p_exclude_product_id IS NULL OR id != p_exclude_product_id)
  ) LOOP
    v_next_number := v_next_number + 1;
    v_next_formatted := LPAD(v_next_number::TEXT, 3, '0');
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'nextNumber', v_next_formatted,
    'nextNumberInt', v_next_number,
    'fullSku', v_prefix_clean || '-' || v_next_formatted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_review(p_order_id uuid, p_product_id uuid, p_review_role text, p_rating integer, p_content text DEFAULT NULL::text, p_title character varying DEFAULT NULL::character varying, p_would_recommend boolean DEFAULT NULL::boolean, p_image_urls text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_order RECORD;
    v_reviewed_user_id UUID;
    v_review_id UUID;
    v_image_url TEXT;
    v_sort_order INTEGER := 0;
    v_notification_title TEXT;
    v_notification_body TEXT;
BEGIN
    -- 1. Auth check
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- 2. Validate role
    IF p_review_role NOT IN ('as_seller', 'as_buyer') THEN
        RAISE EXCEPTION 'Invalid review role. Must be as_seller or as_buyer';
    END IF;

    -- 3. Validate rating
    IF p_rating < 1 OR p_rating > 5 THEN
        RAISE EXCEPTION 'Rating must be between 1 and 5';
    END IF;

    -- 4. Validate content length
    IF p_content IS NOT NULL AND LENGTH(TRIM(p_content)) < 20 THEN
        RAISE EXCEPTION 'Review content must be at least 20 characters';
    END IF;

    IF p_content IS NOT NULL AND LENGTH(p_content) > 500 THEN
        RAISE EXCEPTION 'Review content must not exceed 500 characters';
    END IF;

    -- 5. Max 5 images
    IF p_image_urls IS NOT NULL AND array_length(p_image_urls, 1) > 5 THEN
        RAISE EXCEPTION 'Maximum 5 images allowed per review';
    END IF;

    -- 6. Get order and validate
    SELECT o.id, o.buyer_id, o.seller_id, o.status
    INTO v_order
    FROM orders o
    WHERE o.id = p_order_id AND o.deleted_at IS NULL;

    IF v_order IS NULL THEN
        RAISE EXCEPTION 'Order not found';
    END IF;

    IF v_order.status NOT IN ('delivered', 'refunded') THEN
        RAISE EXCEPTION 'Can only review delivered or refunded orders';
    END IF;

    -- 7. Validate product belongs to order
    IF NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = p_order_id AND oi.product_id = p_product_id) THEN
        RAISE EXCEPTION 'Product not found in this order';
    END IF;

    -- 8. Determine reviewed user based on role
    IF p_review_role = 'as_seller' THEN
        -- I'm the buyer, reviewing the seller
        IF v_order.buyer_id != v_user_id THEN
            RAISE EXCEPTION 'You are not the buyer of this order';
        END IF;
        v_reviewed_user_id := v_order.seller_id;
    ELSE
        -- I'm the seller, reviewing the buyer
        IF v_order.seller_id != v_user_id THEN
            RAISE EXCEPTION 'You are not the seller of this order';
        END IF;
        v_reviewed_user_id := v_order.buyer_id;
    END IF;

    -- 9. Check for existing review (same order + product + reviewer + role)
    IF EXISTS (
        SELECT 1 FROM reviews r
        WHERE r.order_id = p_order_id
          AND r.product_id = p_product_id
          AND r.reviewer_id = v_user_id
          AND r.role = p_review_role::review_role
          AND r.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'You have already reviewed this product for this order';
    END IF;

    -- 10. Create the review
    INSERT INTO reviews (
        reviewer_id,
        reviewed_id,
        order_id,
        product_id,
        role,
        rating,
        title,
        content,
        would_recommend
    )
    VALUES (
        v_user_id,
        v_reviewed_user_id,
        p_order_id,
        p_product_id,
        p_review_role::review_role,
        p_rating,
        p_title,
        TRIM(p_content),
        p_would_recommend
    )
    RETURNING id INTO v_review_id;

    -- 11. Add review images
    IF p_image_urls IS NOT NULL AND array_length(p_image_urls, 1) > 0 THEN
        FOREACH v_image_url IN ARRAY p_image_urls
        LOOP
            INSERT INTO review_images (review_id, image_url, sort_order)
            VALUES (v_review_id, v_image_url, v_sort_order);
            v_sort_order := v_sort_order + 1;
        END LOOP;
    END IF;

    -- 12. Create notification for reviewed user
    IF p_review_role = 'as_seller' THEN
        v_notification_title := 'New Seller Review';
        v_notification_body := 'You received a ' || p_rating || '-star seller review';
    ELSE
        v_notification_title := 'New Buyer Review';
        v_notification_body := 'You received a ' || p_rating || '-star buyer review';
    END IF;

    INSERT INTO notifications (
        user_id, type, title, body,
        related_user_id, related_product_id, related_order_id,
        action_url
    )
    VALUES (
        v_reviewed_user_id, 'new_review', v_notification_title, v_notification_body,
        v_user_id, p_product_id, p_order_id,
        '/reviews/' || v_review_id
    );

    -- 13. Return success
    -- Note: trigger_update_user_rating handles rating recalculation automatically
    RETURN jsonb_build_object(
        'success', true,
        'review_id', v_review_id,
        'rating', p_rating,
        'reviewed_user_id', v_reviewed_user_id,
        'role', p_review_role
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_rating_summary(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_seller_rating NUMERIC;
    v_buyer_rating NUMERIC;
    v_seller_reviews INTEGER;
    v_buyer_reviews INTEGER;
    v_overall_rating NUMERIC;
BEGIN
    SELECT 
        up.rating_as_seller,
        up.rating_as_buyer,
        up.total_reviews_as_seller,
        up.total_reviews_as_buyer
    INTO v_seller_rating, v_buyer_rating, v_seller_reviews, v_buyer_reviews
    FROM user_profiles up
    WHERE up.user_id = p_user_id AND up.deleted_at IS NULL;

    -- Calculate overall rating per spec:
    -- Both exist → average of both
    -- Only one → that one
    -- None → 0
    IF v_seller_reviews > 0 AND v_buyer_reviews > 0 THEN
        v_overall_rating := ROUND((v_seller_rating + v_buyer_rating) / 2.0, 1);
    ELSIF v_seller_reviews > 0 THEN
        v_overall_rating := ROUND(v_seller_rating, 1);
    ELSIF v_buyer_reviews > 0 THEN
        v_overall_rating := ROUND(v_buyer_rating, 1);
    ELSE
        v_overall_rating := 0;
    END IF;

    RETURN jsonb_build_object(
        'user_id', p_user_id,
        'rating_as_seller', ROUND(v_seller_rating, 1),
        'rating_as_buyer', ROUND(v_buyer_rating, 1),
        'total_reviews_as_seller', v_seller_reviews,
        'total_reviews_as_buyer', v_buyer_reviews,
        'overall_rating', v_overall_rating,
        'total_reviews', v_seller_reviews + v_buyer_reviews
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_product(p_title character varying, p_description text, p_category_id uuid, p_sku character varying, p_sku_number character varying DEFAULT NULL::character varying, p_quantity integer DEFAULT 1, p_price numeric DEFAULT 0, p_flash_sale_enabled boolean DEFAULT false, p_use_seller_shipping boolean DEFAULT true, p_status text DEFAULT 'draft'::text, p_subcategory_id uuid DEFAULT NULL::uuid, p_shortlist_id uuid DEFAULT NULL::uuid, p_year integer DEFAULT NULL::integer, p_issue_number integer DEFAULT NULL::integer, p_flash_sale_hours integer DEFAULT NULL::integer, p_discount_type text DEFAULT NULL::text, p_discount_amount numeric DEFAULT NULL::numeric, p_condition_ids uuid[] DEFAULT NULL::uuid[], p_tags uuid[] DEFAULT NULL::uuid[], p_custom_flat_rate numeric DEFAULT NULL::numeric, p_custom_additional_item_fee numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_product_id UUID;
  v_flash_sale_price NUMERIC;
  v_flash_sale_ends_at TIMESTAMPTZ;
  v_original_price NUMERIC;
  v_shipping_price NUMERIC := 0;
  v_flat_rate NUMERIC := 0;
  v_additional_fee NUMERIC := 0;
  v_condition_id UUID;
  v_sku_upper VARCHAR;
  v_sku_number_clean VARCHAR;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  v_sku_upper := UPPER(TRIM(p_sku));
  v_sku_number_clean := NULLIF(TRIM(COALESCE(p_sku_number, '')), '');

  IF EXISTS (
    SELECT 1 FROM products
    WHERE seller_id = v_user_id
      AND UPPER(sku) = v_sku_upper
      AND (
        (v_sku_number_clean IS NULL AND sku_number IS NULL)
        OR sku_number = v_sku_number_clean
      )
      AND deleted_at IS NULL
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'SKU ' || v_sku_upper || COALESCE('-' || v_sku_number_clean, '') || ' already exists.'
    );
  END IF;

  -- Flash sale
  IF p_flash_sale_enabled = TRUE AND p_discount_type IS NOT NULL AND p_discount_amount IS NOT NULL THEN
    v_original_price := p_price;
    IF p_discount_type = 'percentage' THEN
      v_flash_sale_price := ROUND(p_price * (1 - p_discount_amount / 100), 2);
    ELSE
      v_flash_sale_price := ROUND(p_price - p_discount_amount, 2);
    END IF;
    v_flash_sale_ends_at := NOW() + (p_flash_sale_hours::TEXT || ' hours')::INTERVAL;
  END IF;

  -- Shipping
  IF p_use_seller_shipping = TRUE THEN
    SELECT
      COALESCE(default_flat_shipping_rate, 0),
      COALESCE(default_additional_item_fee, 0)
    INTO v_flat_rate, v_additional_fee
    FROM user_settings
    WHERE user_id = v_user_id AND deleted_at IS NULL
    LIMIT 1;
  ELSE
    v_flat_rate := COALESCE(p_custom_flat_rate, 0);
    v_additional_fee := COALESCE(p_custom_additional_item_fee, 0);
  END IF;

  v_shipping_price := v_flat_rate;

  IF p_condition_ids IS NOT NULL AND array_length(p_condition_ids, 1) > 0 THEN
    v_condition_id := p_condition_ids[1];
  END IF;

  INSERT INTO products (
    seller_id, title, description, category_id, subcategory_id,
    sku, sku_number, quantity, price, original_price,
    flash_sale_enabled, flash_sale_price, flash_sale_ends_at,
    shipping_price, use_seller_shipping,
    custom_flat_rate, custom_additional_item_fee,
    condition_id, issue_number,
    discount_type, discount_amount,
    shortlist_id, status, year, published_at
  ) VALUES (
    v_user_id, p_title, p_description, p_category_id, p_subcategory_id,
    v_sku_upper, v_sku_number_clean, p_quantity, p_price, v_original_price,
    COALESCE(p_flash_sale_enabled, FALSE), v_flash_sale_price, v_flash_sale_ends_at,
    v_shipping_price, p_use_seller_shipping,
    v_flat_rate, v_additional_fee,
    v_condition_id, p_issue_number,
    CASE WHEN p_flash_sale_enabled = TRUE THEN p_discount_type ELSE NULL END,
    CASE WHEN p_flash_sale_enabled = TRUE THEN p_discount_amount ELSE NULL END,
    p_shortlist_id, p_status::product_status, p_year,
    CASE WHEN p_status = 'active' THEN NOW() ELSE NULL END
  )
  RETURNING id INTO v_product_id;

  IF p_condition_ids IS NOT NULL AND array_length(p_condition_ids, 1) > 0 THEN
    INSERT INTO product_conditions (product_id, condition_id)
    SELECT v_product_id, unnest(p_condition_ids)
    ON CONFLICT DO NOTHING;
  END IF;

  IF p_tags IS NOT NULL AND array_length(p_tags, 1) > 0 THEN
    INSERT INTO product_tags (product_id, tag_id)
    SELECT v_product_id, unnest(p_tags)
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_product_id);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_product(p_product_id uuid, p_title character varying, p_description text, p_category_id uuid, p_sku character varying, p_sku_number character varying DEFAULT NULL::character varying, p_quantity integer DEFAULT 1, p_price numeric DEFAULT 0, p_flash_sale_enabled boolean DEFAULT false, p_use_seller_shipping boolean DEFAULT true, p_status text DEFAULT 'draft'::text, p_subcategory_id uuid DEFAULT NULL::uuid, p_shortlist_id uuid DEFAULT NULL::uuid, p_year integer DEFAULT NULL::integer, p_issue_number integer DEFAULT NULL::integer, p_flash_sale_hours integer DEFAULT NULL::integer, p_discount_type text DEFAULT NULL::text, p_discount_amount numeric DEFAULT NULL::numeric, p_condition_ids uuid[] DEFAULT NULL::uuid[], p_tags uuid[] DEFAULT NULL::uuid[], p_custom_flat_rate numeric DEFAULT NULL::numeric, p_custom_additional_item_fee numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_flash_sale_price NUMERIC;
  v_flash_sale_ends_at TIMESTAMPTZ;
  v_original_price NUMERIC;
  v_shipping_price NUMERIC := 0;
  v_flat_rate NUMERIC := 0;
  v_additional_fee NUMERIC := 0;
  v_condition_id UUID;
  v_sku_upper VARCHAR;
  v_sku_number_clean VARCHAR;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM products
    WHERE id = p_product_id AND seller_id = v_user_id AND deleted_at IS NULL
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Product not found or access denied');
  END IF;

  v_sku_upper := UPPER(TRIM(p_sku));
  v_sku_number_clean := NULLIF(TRIM(COALESCE(p_sku_number, '')), '');

  IF EXISTS (
    SELECT 1 FROM products
    WHERE seller_id = v_user_id
      AND UPPER(sku) = v_sku_upper
      AND (
        (v_sku_number_clean IS NULL AND sku_number IS NULL)
        OR sku_number = v_sku_number_clean
      )
      AND deleted_at IS NULL
      AND id != p_product_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'SKU ' || v_sku_upper || COALESCE('-' || v_sku_number_clean, '') || ' is already used by another product.'
    );
  END IF;

  -- Flash sale
  IF p_flash_sale_enabled = TRUE AND p_discount_type IS NOT NULL AND p_discount_amount IS NOT NULL THEN
    v_original_price := p_price;
    IF p_discount_type = 'percentage' THEN
      v_flash_sale_price := ROUND(p_price * (1 - p_discount_amount / 100), 2);
    ELSE
      v_flash_sale_price := ROUND(p_price - p_discount_amount, 2);
    END IF;
    v_flash_sale_ends_at := NOW() + (p_flash_sale_hours::TEXT || ' hours')::INTERVAL;
  END IF;

  -- Shipping
  IF p_use_seller_shipping = TRUE THEN
    SELECT
      COALESCE(default_flat_shipping_rate, 0),
      COALESCE(default_additional_item_fee, 0)
    INTO v_flat_rate, v_additional_fee
    FROM user_settings
    WHERE user_id = v_user_id AND deleted_at IS NULL
    LIMIT 1;
  ELSE
    v_flat_rate := COALESCE(p_custom_flat_rate, 0);
    v_additional_fee := COALESCE(p_custom_additional_item_fee, 0);
  END IF;

  v_shipping_price := v_flat_rate;

  IF p_condition_ids IS NOT NULL AND array_length(p_condition_ids, 1) > 0 THEN
    v_condition_id := p_condition_ids[1];
  END IF;

  UPDATE products SET
    title = p_title,
    description = p_description,
    category_id = p_category_id,
    subcategory_id = p_subcategory_id,
    sku = v_sku_upper,
    sku_number = v_sku_number_clean,
    quantity = p_quantity,
    price = p_price,
    original_price = CASE WHEN p_flash_sale_enabled = TRUE THEN p_price ELSE original_price END,
    flash_sale_enabled = COALESCE(p_flash_sale_enabled, FALSE),
    flash_sale_price = v_flash_sale_price,
    flash_sale_ends_at = v_flash_sale_ends_at,
    shipping_price = v_shipping_price,
    use_seller_shipping = p_use_seller_shipping,
    custom_flat_rate = v_flat_rate,
    custom_additional_item_fee = v_additional_fee,
    condition_id = v_condition_id,
    issue_number = p_issue_number,
    discount_type = CASE WHEN p_flash_sale_enabled = TRUE THEN p_discount_type ELSE NULL END,
    discount_amount = CASE WHEN p_flash_sale_enabled = TRUE THEN p_discount_amount ELSE NULL END,
    shortlist_id = p_shortlist_id,
    status = p_status::product_status,
    year = p_year,
    published_at = CASE
      WHEN p_status = 'active' AND published_at IS NULL THEN NOW()
      ELSE published_at
    END,
    updated_at = NOW()
  WHERE id = p_product_id AND seller_id = v_user_id;

  DELETE FROM product_conditions WHERE product_id = p_product_id;
  IF p_condition_ids IS NOT NULL AND array_length(p_condition_ids, 1) > 0 THEN
    INSERT INTO product_conditions (product_id, condition_id)
    SELECT p_product_id, unnest(p_condition_ids)
    ON CONFLICT DO NOTHING;
  END IF;

  DELETE FROM product_tags WHERE product_id = p_product_id;
  IF p_tags IS NOT NULL AND array_length(p_tags, 1) > 0 THEN
    INSERT INTO product_tags (product_id, tag_id)
    SELECT p_product_id, unnest(p_tags)
    ON CONFLICT DO NOTHING;
  END IF;

  DELETE FROM product_images WHERE product_id = p_product_id;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_referral_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    result TEXT := '';
    i INTEGER;
BEGIN
    FOR i IN 1..8 LOOP
        result := result || substr(chars, floor(random() * length(chars) + 1)::integer, 1);
    END LOOP;
    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.toggle_wishlist(p_user_id uuid, p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_exists BOOLEAN;
    v_wishlist_id UUID;
BEGIN

    SELECT id INTO v_wishlist_id
    FROM wishlists
    WHERE user_id = p_user_id AND product_id = p_product_id;

    v_exists := v_wishlist_id IS NOT NULL;

    IF v_exists THEN

        DELETE FROM wishlists WHERE id = v_wishlist_id;
        RETURN jsonb_build_object(
            'success', true,
            'action', 'removed',
            'is_in_wishlist', false
        );
    ELSE

        INSERT INTO wishlists (user_id, product_id)
        VALUES (p_user_id, p_product_id);
        RETURN jsonb_build_object(
            'success', true,
            'action', 'added',
            'is_in_wishlist', true
        );
    END IF;

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_counter_offer(p_counter_offer_id uuid, p_accept boolean)
 RETURNS TABLE(counter_offer_id uuid, status counter_offer_status, responded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_offer RECORD;
    v_new_status counter_offer_status;
    v_message_content TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Получаем offer
    SELECT * INTO v_offer
    FROM counter_offers co
    WHERE co.id = p_counter_offer_id
    AND co.to_user_id = v_user_id
    AND co.status = 'pending';

    IF v_offer IS NULL THEN
        RAISE EXCEPTION 'Counter offer not found or already responded';
    END IF;

    -- Проверяем срок действия
    IF v_offer.expires_at < NOW() THEN
        UPDATE counter_offers SET status = 'expired' WHERE id = p_counter_offer_id;
        RAISE EXCEPTION 'Counter offer has expired';
    END IF;

    -- Определяем новый статус
    v_new_status := CASE WHEN p_accept THEN 'accepted' ELSE 'rejected' END;

    -- Обновляем offer
    UPDATE counter_offers
    SET 
        status = v_new_status,
        responded_at = NOW()
    WHERE id = p_counter_offer_id;

    -- Создаём системное сообщение
    v_message_content := CASE 
        WHEN p_accept THEN 'Accepted the offer of $' || v_offer.offered_price::TEXT
        ELSE 'Declined the offer of $' || v_offer.offered_price::TEXT
    END;

    INSERT INTO messages (
        conversation_id, 
        sender_id, 
        content, 
        message_type,
        counter_offer_id
    ) VALUES (
        v_offer.conversation_id,
        v_user_id,
        v_message_content,
        'counter_offer',
        p_counter_offer_id
    );

    -- Возвращаем результат
    RETURN QUERY
    SELECT 
        co.id,
        co.status,
        co.responded_at
    FROM counter_offers co
    WHERE co.id = p_counter_offer_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_checkout_totals(p_product_id uuid, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product RECORD;
    v_effective_price NUMERIC(10,2);
    v_subtotal NUMERIC(10,2);
    v_shipping_cost NUMERIC(10,2);
    v_tax_amount NUMERIC(10,2);
    v_platform_fee NUMERIC(10,2);
    v_total_amount NUMERIC(10,2);
    v_tax_rate NUMERIC := 0.08;
    v_platform_fee_rate NUMERIC := 0.01;
BEGIN
    SELECT * INTO v_product
    FROM products
    WHERE id = p_product_id AND status = 'active' AND deleted_at IS NULL;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Product not found');
    END IF;

    -- Flash sale check
    IF v_product.flash_sale_enabled = TRUE
       AND v_product.flash_sale_price IS NOT NULL
       AND v_product.flash_sale_ends_at > NOW() THEN
        v_effective_price := v_product.flash_sale_price;
    ELSE
        v_effective_price := v_product.price;
    END IF;

    v_subtotal := v_effective_price * p_quantity;

    -- NEW: flat rate + additional item fee
    v_shipping_cost := calculate_product_shipping(p_product_id, p_quantity);

    v_tax_amount := ROUND(v_subtotal * v_tax_rate, 2);
    v_platform_fee := ROUND(v_subtotal * v_platform_fee_rate, 2);
    v_total_amount := v_subtotal + v_shipping_cost + v_tax_amount + v_platform_fee;

    RETURN jsonb_build_object(
        'success', true,
        'effective_price', v_effective_price,
        'original_price', v_product.price,
        'is_flash_sale', (v_product.flash_sale_enabled AND v_product.flash_sale_ends_at > NOW()),
        'subtotal', v_subtotal,
        'shipping_cost', v_shipping_cost,
        'free_shipping', v_product.free_shipping,
        'tax_amount', v_tax_amount,
        'platform_fee', v_platform_fee,
        'total_amount', v_total_amount,
        'available_quantity', v_product.quantity
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_checkout_order(p_product_id uuid, p_quantity integer DEFAULT 1, p_shipping_address_id uuid DEFAULT NULL::uuid, p_payment_method_id uuid DEFAULT NULL::uuid, p_buyer_notes text DEFAULT NULL::text, p_shortlist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_buyer_id UUID := auth.uid();
    v_product RECORD;
    v_seller_id UUID;
    v_address RECORD;
    v_subtotal NUMERIC(10,2);
    v_shipping_cost NUMERIC(10,2);
    v_tax_amount NUMERIC(10,2);
    v_platform_fee NUMERIC(10,2);
    v_total_amount NUMERIC(10,2);
    v_effective_price NUMERIC(10,2);
    v_order_id UUID;
    v_order_number TEXT;
    v_address_snapshot JSONB;
    v_can_purchase BOOLEAN;
    v_settings RECORD;
    v_tax_rate NUMERIC := 0.08;
    v_platform_fee_rate NUMERIC := 0.01;
BEGIN
    -- 1. Auth
    IF v_buyer_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- 2. Product with lock
    SELECT * INTO v_product
    FROM products
    WHERE id = p_product_id AND deleted_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product not found';
    END IF;

    IF v_product.status != 'active' THEN
        RAISE EXCEPTION 'Product is not available for purchase (status: %)', v_product.status;
    END IF;

    IF v_product.quantity < p_quantity THEN
        RAISE EXCEPTION 'Insufficient stock. Available: %, Requested: %', v_product.quantity, p_quantity;
    END IF;

    v_seller_id := v_product.seller_id;

    -- 3. Can purchase check
    v_can_purchase := can_user_purchase(v_buyer_id, p_product_id);
    IF NOT v_can_purchase THEN
        RAISE EXCEPTION 'You cannot purchase this product';
    END IF;

    -- 4. Budget settings
    SELECT * INTO v_settings
    FROM user_settings
    WHERE user_id = v_buyer_id;

    -- 5. Effective price (flash sale)
    IF v_product.flash_sale_enabled = TRUE
       AND v_product.flash_sale_price IS NOT NULL
       AND v_product.flash_sale_ends_at > NOW() THEN
        v_effective_price := v_product.flash_sale_price;
    ELSE
        v_effective_price := v_product.price;
    END IF;

    -- 6. Calculate totals
    v_subtotal := v_effective_price * p_quantity;

    -- NEW: flat rate + additional item fee
    v_shipping_cost := calculate_product_shipping(p_product_id, p_quantity);

    v_tax_amount := ROUND(v_subtotal * v_tax_rate, 2);
    v_platform_fee := ROUND(v_subtotal * v_platform_fee_rate, 2);
    v_total_amount := v_subtotal + v_shipping_cost + v_tax_amount + v_platform_fee;

    -- 7. Daily budget check
    IF v_settings IS NOT NULL 
       AND v_settings.swipe_payment_enabled = TRUE 
       AND v_settings.daily_budget > 0 THEN
        IF v_settings.budget_reset_at IS NULL OR v_settings.budget_reset_at < DATE_TRUNC('day', NOW()) THEN
            UPDATE user_settings 
            SET daily_budget_used = 0, budget_reset_at = DATE_TRUNC('day', NOW())
            WHERE user_id = v_buyer_id;
            v_settings.daily_budget_used := 0;
        END IF;

        IF (v_settings.daily_budget_used + v_total_amount) > v_settings.daily_budget THEN
            RAISE EXCEPTION 'Daily budget exceeded. Budget: %, Used: %, Order: %', 
                v_settings.daily_budget, v_settings.daily_budget_used, v_total_amount;
        END IF;
    END IF;

    -- 8. Address snapshot
    IF p_shipping_address_id IS NOT NULL THEN
        SELECT * INTO v_address
        FROM shipping_addresses
        WHERE id = p_shipping_address_id AND user_id = v_buyer_id AND deleted_at IS NULL;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Shipping address not found';
        END IF;

        v_address_snapshot := jsonb_build_object(
            'full_name', v_address.full_name,
            'address_line1', v_address.address_line1,
            'address_line2', v_address.address_line2,
            'city', v_address.city,
            'state', v_address.state,
            'zip_code', v_address.zip_code,
            'country', v_address.country,
            'phone', v_address.phone
        );
    END IF;

    -- 9. Create order
    INSERT INTO orders (
        buyer_id, seller_id, subtotal, shipping_cost, tax_amount,
        platform_fee, total_amount, shipping_address_id, 
        shipping_address_snapshot, payment_method_id, buyer_notes,
        shortlist_id, status
    ) VALUES (
        v_buyer_id, v_seller_id, v_subtotal, v_shipping_cost, v_tax_amount,
        v_platform_fee, v_total_amount, p_shipping_address_id,
        v_address_snapshot, p_payment_method_id, p_buyer_notes,
        p_shortlist_id, 'pending'
    )
    RETURNING id, order_number INTO v_order_id, v_order_number;

    -- 10. Order item
    INSERT INTO order_items (order_id, product_id, product_title, product_price, quantity)
    VALUES (v_order_id, p_product_id, v_product.title, v_effective_price, p_quantity);

    -- 11. Result
    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'order_number', v_order_number,
        'subtotal', v_subtotal,
        'shipping_cost', v_shipping_cost,
        'tax_amount', v_tax_amount,
        'platform_fee', v_platform_fee,
        'total_amount', v_total_amount
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_order_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    seq_val BIGINT;
BEGIN
    -- Advisory lock prevents concurrent generation issues
    PERFORM pg_advisory_xact_lock(hashtext('order_number_gen'));
    seq_val := nextval('order_number_seq');
    RETURN 'ORD-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(seq_val::TEXT, 6, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_follower_counts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE user_profiles SET followers_count = LEAST(followers_count + 1, 100000000)
        WHERE user_id = NEW.following_id;
        UPDATE user_profiles SET following_count = LEAST(following_count + 1, 100000000)
        WHERE user_id = NEW.follower_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE user_profiles SET followers_count = GREATEST(0, followers_count - 1)
        WHERE user_id = OLD.following_id;
        UPDATE user_profiles SET following_count = GREATEST(0, following_count - 1)
        WHERE user_id = OLD.follower_id;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_video_likes_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE videos SET likes_count = LEAST(likes_count + 1, 2147483647) WHERE id = NEW.video_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE videos SET likes_count = GREATEST(0, likes_count - 1) WHERE id = OLD.video_id;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_shortlist_item_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE shortlists SET total_items = total_items + 1 WHERE id = NEW.shortlist_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE shortlists SET total_items = GREATEST(0, total_items - 1) WHERE id = OLD.shortlist_id;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_message(p_conversation_id uuid, p_content text, p_image_urls text[] DEFAULT NULL::text[])
 RETURNS TABLE(id uuid, conversation_id uuid, sender_id uuid, content text, message_type message_type, is_read boolean, created_at timestamp with time zone, images jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_message_id UUID;
    v_message_type message_type;
    v_content TEXT;
    v_array_length INT;
    i INT;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    v_content := TRIM(COALESCE(p_content, ''));
    v_array_length := COALESCE(array_length(p_image_urls, 1), 0);

    IF v_array_length > 0 THEN
        v_message_type := 'image';
    ELSE
        v_message_type := 'text';
        IF v_content = '' THEN
            RAISE EXCEPTION 'Message content cannot be empty';
        END IF;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM conversations c
        WHERE c.id = p_conversation_id
        AND (c.buyer_id = v_user_id OR c.seller_id = v_user_id)
        AND c.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Access denied: not a participant';
    END IF;

    -- Вот фикс: вместо NULLIF просто v_content (пустая строка вместо NULL)
    INSERT INTO messages (conversation_id, sender_id, content, message_type)
    VALUES (p_conversation_id, v_user_id, v_content, v_message_type)
    RETURNING messages.id INTO v_message_id;

    IF v_array_length > 0 THEN
        FOR i IN 1..v_array_length LOOP
            INSERT INTO message_images (message_id, image_url, sort_order)
            VALUES (v_message_id, p_image_urls[i], i - 1);
        END LOOP;
    END IF;

    RETURN QUERY
    SELECT 
        m.id,
        m.conversation_id,
        m.sender_id,
        m.content,
        m.message_type,
        m.is_read,
        m.created_at,
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', mi.id,
                        'image_url', mi.image_url,
                        'thumbnail_url', mi.thumbnail_url,
                        'width', mi.width,
                        'height', mi.height
                    ) ORDER BY mi.sort_order
                )
                FROM message_images mi
                WHERE mi.message_id = m.id
            ),
            '[]'::jsonb
        ) AS images
    FROM messages m
    WHERE m.id = v_message_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_user_stats_on_order_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.status = 'pending' AND NEW.status = 'paid' THEN
        UPDATE user_profiles SET total_sales = LEAST(total_sales + 1, 100000000)
        WHERE user_id = NEW.seller_id;

        UPDATE user_profiles SET total_purchases = LEAST(total_purchases + 1, 100000000)
        WHERE user_id = NEW.buyer_id;

        UPDATE products SET status = 'sold', sold_at = NOW()
        WHERE id IN (SELECT product_id FROM order_items WHERE order_id = NEW.id);
    END IF;

    IF NEW.status = 'refunded' AND OLD.status != 'refunded' THEN
        UPDATE user_profiles SET total_refunds = LEAST(total_refunds + 1, 100000000)
        WHERE user_id = NEW.seller_id;
    END IF;

    IF OLD.status = 'pending' AND NEW.status = 'cancelled' THEN
        UPDATE user_profiles SET total_cancelled = LEAST(total_cancelled + 1, 100000000)
        WHERE user_id = NEW.seller_id;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_single_default_address()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    lock_id BIGINT;
BEGIN
    IF NEW.is_default = TRUE THEN
        lock_id := ('x' || substr(md5(NEW.user_id::text), 1, 16))::bit(64)::bigint;
        PERFORM pg_advisory_xact_lock(lock_id);

        UPDATE shipping_addresses 
        SET is_default = FALSE 
        WHERE user_id = NEW.user_id 
          AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
          AND is_default = TRUE
          AND deleted_at IS NULL;
    END IF;
    RETURN NEW;
END;
$function$

