CREATE OR REPLACE FUNCTION public.check_max_product_images()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    image_count INTEGER;
    lock_id BIGINT;
BEGIN
    lock_id := ('x' || substr(md5('img_count_' || NEW.product_id::text), 1, 16))::bit(64)::bigint;
    PERFORM pg_advisory_xact_lock(lock_id);

    SELECT COUNT(*) INTO image_count FROM product_images WHERE product_id = NEW.product_id;

    IF image_count >= 10 THEN
        RAISE EXCEPTION 'Maximum 10 images per product allowed';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_sync_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_integration_id UUID;
    v_has_mapping BOOLEAN;
BEGIN
    IF NEW.status = 'sold' AND OLD.status != 'sold' THEN
        SELECT psm.integration_id, TRUE
        INTO v_integration_id, v_has_mapping
        FROM product_shopify_mapping psm
        JOIN shopify_integrations si ON si.id = psm.integration_id
        WHERE psm.product_id = NEW.id AND si.is_active = TRUE AND si.auto_sync_enabled = TRUE
        LIMIT 1;

        IF v_has_mapping THEN
            INSERT INTO sync_jobs (user_id, integration_id, direction, sync_type, scope, status)
            VALUES (NEW.seller_id, v_integration_id, 'export', 'auto',
                    jsonb_build_object('product_ids', ARRAY[NEW.id], 'action', 'mark_sold'), 'pending');
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.encrypt_shopify_secrets()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_key TEXT;
BEGIN
    BEGIN
        v_key := current_setting('app.encryption_key', true);
    EXCEPTION WHEN OTHERS THEN
        v_key := NULL;
    END;

    IF v_key IS NOT NULL THEN
        IF NEW.webhook_secret IS NOT NULL 
           AND (TG_OP = 'INSERT' OR OLD.webhook_secret IS DISTINCT FROM NEW.webhook_secret)
           AND NEW.webhook_secret NOT LIKE 'ENC:%' THEN
            NEW.webhook_secret := 'ENC:' || encode(pgp_sym_encrypt(NEW.webhook_secret, v_key), 'base64');
        END IF;

        IF NEW.access_token IS NOT NULL 
           AND (TG_OP = 'INSERT' OR OLD.access_token IS DISTINCT FROM NEW.access_token)
           AND NEW.access_token NOT LIKE 'ENC:%' THEN
            NEW.access_token := 'ENC:' || encode(pgp_sym_encrypt(NEW.access_token, v_key), 'base64');
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_trigger_func()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_ip INET;
    v_user_agent TEXT;
BEGIN
    BEGIN
        v_ip := (current_setting('request.headers', true)::json->>'x-forwarded-for')::inet;
    EXCEPTION WHEN OTHERS THEN
        v_ip := NULL;
    END;

    BEGIN
        v_user_agent := current_setting('request.headers', true)::json->>'user-agent';
    EXCEPTION WHEN OTHERS THEN
        v_user_agent := NULL;
    END;

    IF TG_OP = 'DELETE' THEN
        INSERT INTO audit_logs (table_name, record_id, action, old_data, user_id, ip_address, user_agent)
        VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', to_jsonb(OLD), auth.uid(), v_ip, v_user_agent);
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, user_id, ip_address, user_agent)
        VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', to_jsonb(OLD), to_jsonb(NEW), auth.uid(), v_ip, v_user_agent);
        RETURN NEW;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO audit_logs (table_name, record_id, action, new_data, user_id, ip_address, user_agent)
        VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', to_jsonb(NEW), auth.uid(), v_ip, v_user_agent);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_audit_logs(p_days integer DEFAULT 180)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_deleted INTEGER;
BEGIN
    DELETE FROM audit_logs WHERE created_at < NOW() - (p_days || ' days')::interval;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RAISE NOTICE 'Deleted % audit logs', v_deleted;
    RETURN v_deleted;
END;
$function$

