    DELETE FROM sync_logs WHERE created_at < NOW() - (p_days || ' days')::interval;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RAISE NOTICE 'Deleted % sync logs', v_deleted;
    RETURN v_deleted;
END;
$function$

CREATE OR REPLACE FUNCTION public.track_product_view(p_product_id uuid, p_viewer_id uuid DEFAULT NULL::uuid, p_source character varying DEFAULT NULL::character varying)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_last_view TIMESTAMPTZ;
    v_rate_limit_seconds INTEGER := 60;
BEGIN
    -- For anonymous users, always allow
    IF p_viewer_id IS NULL THEN
        INSERT INTO product_views (product_id, viewer_id, source, viewed_at)
        VALUES (p_product_id, NULL, p_source, NOW());
        RETURN TRUE;
    END IF;

    -- Check last view time for this user+product
    SELECT MAX(viewed_at) INTO v_last_view
    FROM product_views
    WHERE product_id = p_product_id 
      AND viewer_id = p_viewer_id
      AND viewed_at > NOW() - (v_rate_limit_seconds || ' seconds')::interval;

    -- If no recent view, insert
    IF v_last_view IS NULL THEN
        INSERT INTO product_views (product_id, viewer_id, source, viewed_at)
        VALUES (p_product_id, p_viewer_id, p_source, NOW());
        RETURN TRUE;
    END IF;

    -- Rate limited
    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_purchase(p_buyer_id uuid, p_product_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_seller_id UUID;
    v_is_blocked BOOLEAN;
BEGIN
    SELECT seller_id INTO v_seller_id FROM products WHERE id = p_product_id;

    SELECT EXISTS (
        SELECT 1 FROM blocked_users 
        WHERE (blocker_id = v_seller_id AND blocked_id = p_buyer_id)
           OR (blocker_id = p_buyer_id AND blocked_id = v_seller_id)
    ) INTO v_is_blocked;

    RETURN v_seller_id != p_buyer_id AND NOT v_is_blocked;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_bulk_sync_job(p_user_id uuid, p_direction sync_direction, p_filters jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_integration_id UUID;
    v_job_id UUID;
    v_item_count INTEGER;
BEGIN
    SELECT id INTO v_integration_id
    FROM shopify_integrations
    WHERE user_id = p_user_id AND is_active = TRUE AND deleted_at IS NULL
    LIMIT 1;

    IF v_integration_id IS NULL THEN
        RAISE EXCEPTION 'No active Shopify integration found';
    END IF;

    IF p_direction = 'export' THEN
        SELECT COUNT(*) INTO v_item_count
        FROM get_products_for_export(p_user_id, v_integration_id, p_filters);
    ELSE
        v_item_count = 0;
    END IF;

    INSERT INTO sync_jobs (user_id, integration_id, direction, sync_type, scope, total_items, status)
    VALUES (p_user_id, v_integration_id, p_direction, 'manual',
            COALESCE(p_filters, '{"all": true}'::jsonb), v_item_count, 'pending')
    RETURNING id INTO v_job_id;

    RETURN v_job_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_decrypted_shopify_token(p_integration_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_key TEXT;
    v_encrypted TEXT;
    v_user_id UUID;
BEGIN
    SELECT user_id, access_token INTO v_user_id, v_encrypted
    FROM shopify_integrations WHERE id = p_integration_id;

    IF v_user_id != auth.uid() AND NOT is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    BEGIN
        v_key := current_setting('app.encryption_key', true);
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;

    IF v_key IS NULL OR v_encrypted IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_encrypted LIKE 'ENC:%' THEN
        RETURN pgp_sym_decrypt(decode(substring(v_encrypted from 5), 'base64'), v_key);
    END IF;

    RETURN v_encrypted;
END;
$function$

CREATE OR REPLACE FUNCTION public.has_role(p_role text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
    v_roles TEXT[];
BEGIN
    v_roles := ARRAY(
        SELECT jsonb_array_elements_text(
            CASE 
                WHEN jsonb_typeof(auth.jwt() -> 'app_metadata' -> 'roles') = 'array' 
                THEN auth.jwt() -> 'app_metadata' -> 'roles'
                ELSE jsonb_build_array(auth.jwt() -> 'app_metadata' ->> 'role')
            END
        )
    );
    RETURN p_role = ANY(v_roles);
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- CRITICAL: Prevent changing buyer_id or seller_id
    IF OLD.buyer_id IS DISTINCT FROM NEW.buyer_id THEN
        RAISE EXCEPTION 'Cannot change order buyer';
    END IF;

    IF OLD.seller_id IS DISTINCT FROM NEW.seller_id THEN
        RAISE EXCEPTION 'Cannot change order seller';
    END IF;

    -- If buyer is updating (not the seller)
    IF OLD.buyer_id = auth.uid() AND OLD.seller_id != auth.uid() THEN
        IF OLD.status != NEW.status AND NOT (OLD.status = 'pending' AND NEW.status = 'cancelled') THEN
            RAISE EXCEPTION 'Buyers cannot change order status (except cancel pending)';
        END IF;

        IF OLD.subtotal != NEW.subtotal OR OLD.shipping_cost != NEW.shipping_cost OR
           OLD.tax_amount != NEW.tax_amount OR OLD.platform_fee != NEW.platform_fee OR
           OLD.total_amount != NEW.total_amount THEN
            RAISE EXCEPTION 'Buyers cannot modify financial fields';
        END IF;

        IF OLD.tracking_number IS DISTINCT FROM NEW.tracking_number OR
           OLD.shipping_carrier IS DISTINCT FROM NEW.shipping_carrier OR
           OLD.shipping_status IS DISTINCT FROM NEW.shipping_status THEN
            RAISE EXCEPTION 'Buyers cannot modify shipping fields';
        END IF;

        IF OLD.seller_notes IS DISTINCT FROM NEW.seller_notes THEN
            RAISE EXCEPTION 'Buyers cannot modify seller notes';
        END IF;
    END IF;

    -- If seller is updating (not the buyer)
    IF OLD.seller_id = auth.uid() AND OLD.buyer_id != auth.uid() THEN
        IF OLD.status != NEW.status THEN
            IF NOT ((OLD.status = 'paid' AND NEW.status = 'shipped') OR
                    (OLD.status = 'shipped' AND NEW.status = 'delivered')) THEN
                RAISE EXCEPTION 'Sellers can only update status: paid->shipped or shipped->delivered';
            END IF;
        END IF;

        IF OLD.subtotal != NEW.subtotal OR OLD.shipping_cost != NEW.shipping_cost OR
           OLD.tax_amount != NEW.tax_amount OR OLD.platform_fee != NEW.platform_fee OR
           OLD.total_amount != NEW.total_amount THEN
            RAISE EXCEPTION 'Sellers cannot modify financial fields';
        END IF;

        IF OLD.buyer_notes IS DISTINCT FROM NEW.buyer_notes THEN
            RAISE EXCEPTION 'Sellers cannot modify buyer notes';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.track_product_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_changed_fields JSONB := '[]'::jsonb;
    v_old_values JSONB := '{}'::jsonb;
    v_new_values JSONB := '{}'::jsonb;
BEGIN
    -- Track title changes
    IF OLD.title IS DISTINCT FROM NEW.title THEN
        v_changed_fields := v_changed_fields || '"title"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('title', OLD.title);
        v_new_values := v_new_values || jsonb_build_object('title', NEW.title);
    END IF;

    -- Track description changes
    IF OLD.description IS DISTINCT FROM NEW.description THEN
        v_changed_fields := v_changed_fields || '"description"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('description', LEFT(OLD.description, 500));
        v_new_values := v_new_values || jsonb_build_object('description', LEFT(NEW.description, 500));
    END IF;

    -- Track price changes
    IF OLD.price IS DISTINCT FROM NEW.price THEN
        v_changed_fields := v_changed_fields || '"price"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('price', OLD.price);
        v_new_values := v_new_values || jsonb_build_object('price', NEW.price);
    END IF;

    -- Track quantity changes
    IF OLD.quantity IS DISTINCT FROM NEW.quantity THEN
        v_changed_fields := v_changed_fields || '"quantity"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('quantity', OLD.quantity);
        v_new_values := v_new_values || jsonb_build_object('quantity', NEW.quantity);
    END IF;

    -- Track status changes
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        v_changed_fields := v_changed_fields || '"status"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('status', OLD.status);
        v_new_values := v_new_values || jsonb_build_object('status', NEW.status);
    END IF;

    -- NEW: Track category changes
    IF OLD.category_id IS DISTINCT FROM NEW.category_id THEN
        v_changed_fields := v_changed_fields || '"category_id"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('category_id', OLD.category_id);
        v_new_values := v_new_values || jsonb_build_object('category_id', NEW.category_id);
    END IF;

    -- NEW: Track subcategory changes
    IF OLD.subcategory_id IS DISTINCT FROM NEW.subcategory_id THEN
        v_changed_fields := v_changed_fields || '"subcategory_id"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('subcategory_id', OLD.subcategory_id);
        v_new_values := v_new_values || jsonb_build_object('subcategory_id', NEW.subcategory_id);
    END IF;

    -- NEW: Track condition changes
    IF OLD.condition_id IS DISTINCT FROM NEW.condition_id THEN
        v_changed_fields := v_changed_fields || '"condition_id"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('condition_id', OLD.condition_id);
        v_new_values := v_new_values || jsonb_build_object('condition_id', NEW.condition_id);
    END IF;

    -- NEW: Track flash sale changes
    IF OLD.flash_sale_enabled IS DISTINCT FROM NEW.flash_sale_enabled OR
       OLD.flash_sale_price IS DISTINCT FROM NEW.flash_sale_price THEN
        v_changed_fields := v_changed_fields || '"flash_sale"'::jsonb;
        v_old_values := v_old_values || jsonb_build_object('flash_sale_enabled', OLD.flash_sale_enabled, 'flash_sale_price', OLD.flash_sale_price);
        v_new_values := v_new_values || jsonb_build_object('flash_sale_enabled', NEW.flash_sale_enabled, 'flash_sale_price', NEW.flash_sale_price);
    END IF;

    -- Only insert if there were tracked changes
    IF v_changed_fields != '[]'::jsonb THEN
        INSERT INTO product_history (product_id, changed_fields, old_values, new_values, changed_by)
        VALUES (NEW.id, v_changed_fields, v_old_values, v_new_values, auth.uid());
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_tag_usage_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE tags SET usage_count = usage_count + 1 WHERE id = NEW.tag_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE tags SET usage_count = GREATEST(0, usage_count - 1) WHERE id = OLD.tag_id;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_next_month_partitions()
 RETURNS TABLE(table_name text, partition_name text, created boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_next_month DATE;
    v_month_after DATE;
    v_partition_suffix TEXT;
BEGIN
    v_next_month := DATE_TRUNC('month', NOW() + INTERVAL '1 month');
    v_month_after := v_next_month + INTERVAL '1 month';
    v_partition_suffix := TO_CHAR(v_next_month, 'YYYY_MM');

    -- Product views partition
    BEGIN
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS product_views_%s PARTITION OF product_views FOR VALUES FROM (%L) TO (%L)',
            v_partition_suffix, v_next_month, v_month_after
        );
        RETURN QUERY SELECT 'product_views'::TEXT, 'product_views_' || v_partition_suffix, TRUE;
    EXCEPTION WHEN duplicate_table THEN
        RETURN QUERY SELECT 'product_views'::TEXT, 'product_views_' || v_partition_suffix, FALSE;
    END;

    -- For sync_logs and audit_logs we use quarterly partitions
    -- Check if we need a new quarter
    IF EXTRACT(MONTH FROM v_next_month) IN (1, 4, 7, 10) THEN
        DECLARE
            v_quarter_start DATE := DATE_TRUNC('quarter', v_next_month);
            v_quarter_end DATE := v_quarter_start + INTERVAL '3 months';
            v_quarter_suffix TEXT := TO_CHAR(v_quarter_start, 'YYYY') || '_q' || EXTRACT(QUARTER FROM v_quarter_start);
        BEGIN
            -- Sync logs partition
            BEGIN
                EXECUTE format(
                    'CREATE TABLE IF NOT EXISTS sync_logs_%s PARTITION OF sync_logs FOR VALUES FROM (%L) TO (%L)',
                    v_quarter_suffix, v_quarter_start, v_quarter_end
                );
                RETURN QUERY SELECT 'sync_logs'::TEXT, 'sync_logs_' || v_quarter_suffix, TRUE;
            EXCEPTION WHEN duplicate_table THEN
                RETURN QUERY SELECT 'sync_logs'::TEXT, 'sync_logs_' || v_quarter_suffix, FALSE;
            END;

            -- Audit logs partition
            BEGIN
                EXECUTE format(
                    'CREATE TABLE IF NOT EXISTS audit_logs_%s PARTITION OF audit_logs FOR VALUES FROM (%L) TO (%L)',
                    v_quarter_suffix, v_quarter_start, v_quarter_end
                );
                RETURN QUERY SELECT 'audit_logs'::TEXT, 'audit_logs_' || v_quarter_suffix, TRUE;
            EXCEPTION WHEN duplicate_table THEN
                RETURN QUERY SELECT 'audit_logs'::TEXT, 'audit_logs_' || v_quarter_suffix, FALSE;
            END;
        END;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.drop_old_partitions(p_table_name text, p_keep_months integer DEFAULT 12)
 RETURNS TABLE(dropped_partition text, row_count bigint)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_partition RECORD;
    v_cutoff_date DATE := DATE_TRUNC('month', NOW() - (p_keep_months || ' months')::INTERVAL);
    v_row_count BIGINT;
BEGIN
    FOR v_partition IN
        SELECT c.relname AS partition_name
        FROM pg_inherits i
        JOIN pg_class c ON i.inhrelid = c.oid
        JOIN pg_class p ON i.inhparent = p.oid
        WHERE p.relname = p_table_name
        AND c.relname NOT LIKE '%_default'
        ORDER BY c.relname
    LOOP
        -- Extract date from partition name and check if old enough
        -- Assumes format: tablename_YYYY_MM or tablename_YYYY_qN
        DECLARE
            v_partition_date DATE;
        BEGIN
            IF v_partition.partition_name ~ '_\d{4}_\d{2}$' THEN
                -- Monthly partition: table_2024_01
                v_partition_date := TO_DATE(
                    SUBSTRING(v_partition.partition_name FROM '_(\d{4}_\d{2})$'),
                    'YYYY_MM'
                );
            ELSIF v_partition.partition_name ~ '_\d{4}_q\d$' THEN
                -- Quarterly partition: table_2024_q1
                v_partition_date := TO_DATE(
                    SUBSTRING(v_partition.partition_name FROM '_(\d{4})_q') || '-' ||
                    (SUBSTRING(v_partition.partition_name FROM '_q(\d)$')::INT * 3 - 2)::TEXT || '-01',
                    'YYYY-MM-DD'
                );
            ELSE
                CONTINUE;
            END IF;

            IF v_partition_date < v_cutoff_date THEN
                -- Get row count before dropping
                EXECUTE format('SELECT COUNT(*) FROM %I', v_partition.partition_name) INTO v_row_count;

                -- Drop the partition
                EXECUTE format('DROP TABLE IF EXISTS %I', v_partition.partition_name);

                RETURN QUERY SELECT v_partition.partition_name, v_row_count;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- Skip partitions with unparseable names
            CONTINUE;
        END;
    END LOOP;
END;
$function$
